import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { LoopbackLast, LoopbackPending } from '../types'
import { addOutcome, collect, contextOf, fresh, fromStore, gate, rateLine, settle, summaryOf, UNVERIFIED } from './findings'

const STORE_KEY = 'outcomes'

const fed = atom({ plugin: 'loopback', key: 'fed' } as const, [] as string[])
const last = atom({ plugin: 'loopback', key: 'last' } as const, null as LoopbackLast | null)
const pending = atom({ plugin: 'loopback', key: 'pending' } as const, null as LoopbackPending | null)

// The detectors' values, read only: their owners alone write them.
const auditLatest = { plugin: 'self-audit', key: 'latest' } as const
const auditViolations = { plugin: 'self-audit', key: 'violations' } as const
const unverified = { plugin: 'done-gate', key: 'isFlagged' } as const
const denials = { plugin: 'sandbox-lens', key: 'denials' } as const
// Rules hit-rate found too often wrong; empty while hit-rate is off or not installed.
const muted = { plugin: 'hit-rate', key: 'muted' } as const

// $.store has no versioned write: this module's writes run one after another. Across
// sessions the total is read back, and when another session wrote over it in between, this
// outcome is added to theirs and written once more, as todo-agent does.
let queue: Promise<unknown> = Promise.resolve()

function count($: EngineInterface, outcome: { fed: number; repeated: number }): Promise<void> {
  const run = queue.then(async () => {
    const wrote = addOutcome(fromStore(await $.store.get(STORE_KEY)), outcome)
    await $.store.set(STORE_KEY, wrote)
    const stored = fromStore(await $.store.get(STORE_KEY))
    const isOverwritten = stored.fed !== wrote.fed || stored.repeated !== wrote.repeated || stored.checks !== wrote.checks
    if (isOverwritten) await $.store.set(STORE_KEY, addOutcome(stored, outcome))
  })
  queue = run.catch(() => undefined)
  return run
}

export const register: Register = (on, options) => {
  const isEnabled = options.enabled === true

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'loopback', description: 'loopback が最後にモデルへ返した発見と、self-audit 再発率を表示' })
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    // Only what the person typed at an idle prompt: never a command, a hidden prompt, a
    // prompt typed over a running turn, or one a plugin sent.
    if (!isEnabled || e.origin.kind !== 'composer' || e.command !== undefined || e.isMeta || e.turnId !== undefined) {
      return next(e)
    }

    const [latest, violations, isFlagged, held, silenced] = await Promise.all([
      $.state.get(auditLatest),
      $.state.get(auditViolations),
      $.state.get(unverified),
      $.state.get(denials),
      $.state.get(muted),
    ])
    const selfAudit = { latest: latest.value, violations: violations.value }

    const settled = settle(await read($, pending), selfAudit.latest, selfAudit.violations)
    if (settled.outcome !== null) {
      await count($, settled.outcome)
      await update($, pending, () => settled.pending)
    }

    const found = gate(collect({ selfAudit, isUnverified: isFlagged.value === true, denials: held.value }), silenced.value)
    const picked = fresh(found, await read($, fed), isFlagged.value === true)
    if (picked.feed.length === 0) {
      await update($, fed, () => picked.fed)
      return next(e)
    }

    // Counted as fed only once the prompt entered: a hook beneath that drops it (prompt-coach
    // holding an ambiguous prompt) leaves the findings for the next one.
    const ran = await next({ ...e, context: [...(e.context ?? []), contextOf(picked.feed)] })
    if (ran.drop !== undefined) return ran

    // The prompt has entered: nothing here may throw into the .catch below, which would send it again.
    try {
      await update($, fed, () => picked.fed)
      const audited = picked.feed.filter(f => f.source === 'self-audit')
      if (audited.length > 0 && selfAudit.latest?.status === 'audited') {
        const turnId = selfAudit.latest.turnId
        const rules = audited.map(f => f.key.slice(`self-audit:${turnId}:`.length))
        await update($, pending, () => ({ turnId, rules }))
      }
      const at = await $.clock.now()
      await update($, last, () => ({ at, findings: picked.feed }))
      $.ui.toast(summaryOf(picked.feed))
    } catch (err) {
      $.ui.log(`loopback: ${String(err)}`, { to: 'debug' })
    }
    return ran
  }).catch(($, e, next) => next(e))

  // done-gate takes its flag down when a check passes and raises it again at the end of a turn
  // with new edits unverified, both possibly between two prompts. Seen down after a tool call,
  // the episode fed is over, so the next one is fed again rather than taken for the same. The
  // order of the two mods' hooks does not matter: raising it again takes an edit, itself a tool
  // call after the check, and done-gate raises it only at turn.complete, after that edit's call.
  if (isEnabled) on('tool.call', async ($, e, next) => {
    const ran = await next(e)
    try {
      if ((await read($, fed)).includes(UNVERIFIED) && (await $.state.get(unverified)).value !== true) {
        await update($, fed, keys => keys.filter(key => key !== UNVERIFIED))
      }
    } catch (err) {
      $.ui.log(`loopback: ${String(err)}`, { to: 'debug' })
    }
    return ran
  })

  on('command.run', { command: 'loopback' }, async $ => {
    const shown = await read($, last)
    const silenced = (await $.state.get(muted)).value ?? []
    const rate = [
      rateLine(fromStore(await $.store.get(STORE_KEY))),
      ...(silenced.length === 0 ? [] : [`hit-rate により返していないルール: ${silenced.join(', ')}`]),
    ].join('\n')
    const state = isEnabled ? '有効' : '無効（/plugin configure loopback で有効化）'
    if (shown === null) return { text: [`loopback: ${state}`, 'このセッションではまだ何も返していません。', rate].join('\n') }
    return {
      text: [
        `loopback: ${state}`,
        `最後に返した発見（${new Date(shown.at).toLocaleTimeString()}）:`,
        ...shown.findings.map(f => `- [${f.source}] ${f.text}`),
        rate,
      ].join('\n'),
    }
  })
}

